r"""
sync_files.py -- writes every Zone Intelligence Agent file to its exact
repo-relative path, byte-for-byte, using base64-encoded content embedded
directly in this script. No downloading, no copy-paste, no version drift.

Run this from your repo ROOT (e.g. C:/Users/shiya/Desktop/sentinel):

    python sync_files.py

It will create any missing folders and OVERWRITE these files if they
already exist, printing each path as it writes it.
"""
import base64
import os

FILES = {
    "sentinel_contracts/events/zone_state_v1.py": """""",
    "sentinel_contracts/events/zone_anomaly_detected_v1.py": """""",
    "agents/zone_intelligence_agent/zone_intelligence_agent.py": """""",
    "agents/zone_intelligence_agent/config.py": """""",
    "agents/zone_intelligence_agent/graph_projection_service.py": """""",
    "agents/zone_intelligence_agent/main.py": """""",
    "agents/zone_intelligence_agent/acceptance_check.py": """""",
    "agents/zone_intelligence_agent/scenario_simulator.py": """""",
    "agents/zone_intelligence_agent/demo.py": """""",
    "libs/sentinel_state/redis_repositories.py": """""",
    "libs/sentinel_state/postgres_repositories.py": """""",
    "libs/sentinel_state/graph_repositories.py": """""",
    "libs/sentinel_state/container.py": """""",
    "libs/sentinel_state/__init__.py": """""",
}


def main():
    for relpath, b64_content in FILES.items():
        content = base64.b64decode(b64_content)
        os.makedirs(os.path.dirname(relpath) or ".", exist_ok=True)
        with open(relpath, "wb") as f:
            f.write(content)
        print(f"wrote {relpath} ({len(content)} bytes)")
    print(f"\nDone -- {len(FILES)} files written.")


if __name__ == "__main__":
    main()
